Node 22 ESM, TypeScript 5.9.3. Run npm run typecheck and npm test. Source imports use .js extensions; exported functions declare return types. This module is the external input boundary; input has type unknown and is a JSON-decoded value (no getters, proxies, cycles, or custom prototypes).

The wire body must be a non-null object, not an array. sensorId must be a string whose trimmed length is 1..32; output uses the trimmed ID. unit must be exactly C or F. readings must be an array containing 1..100 objects (not null or arrays). Each reading has atMs, a nonnegative safe integer, and value, a finite number in inclusive range -80..80 for C or -112..176 for F. atMs values must be strictly increasing. Strings are not numbers. Any invalid field invalidates the whole batch with {ok:false,error:"invalid-batch"}; partial acceptance is not supported. Unknown properties are ignored.

Output contains only sensorId and readings; each output reading contains only atMs and celsius. Convert F using (value - 32) * 5 / 9; do not round. C values are unchanged. The caller owns the input and may mutate it after decoding. Successful output must be independent of input arrays and objects; decoding must not mutate input. The trusted domain helper temperatureRange receives a valid nonempty SensorBatch.
export interface Reading {
  readonly atMs: number;
  readonly celsius: number;
}

export interface SensorBatch {
  readonly sensorId: string;
  readonly readings: readonly Reading[];
}

export type BatchResult =
  | { readonly ok: true; readonly batch: SensorBatch }
  | { readonly ok: false; readonly error: "invalid-batch" };

interface WireReading {
  atMs: number;
  value: number;
}

interface WireBatch {
  sensorId: string;
  unit: "C" | "F";
  readings: WireReading[];
}

function toCelsius(value: number, unit: "C" | "F"): number {
  return unit === "F" ? ((value - 32) * 5) / 9 : value;
}

// The gateway originally supplied only batches from our own simulator.
export function decodeBatch(input: unknown): BatchResult {
  const wire = input as WireBatch;
  return {
    ok: true,
    batch: {
      sensorId: wire.sensorId.trim(),
      readings: wire.readings.map((reading) => ({
        atMs: reading.atMs,
        celsius: toCelsius(reading.value, wire.unit),
      })),
    },
  };
}

export interface TemperatureRange {
  readonly minimum: number;
  readonly maximum: number;
}

export function temperatureRange(batch: SensorBatch): TemperatureRange {
  let minimum = Infinity;
  let maximum = -Infinity;
  for (const reading of batch.readings) {
    minimum = Math.min(minimum, reading.celsius);
    maximum = Math.max(maximum, reading.celsius);
  }
  return { minimum, maximum };
}
